using System;using System.Linq;using System.Collections;using System.Collections.Generic;
namespace Folha {
/** Windows edits typed text; tablet ink and images remain immutable through this UI bridge. */
static class DesktopEdits {
 static bool Number(object v){return v is byte||v is sbyte||v is short||v is ushort||v is int||v is uint||v is long||v is ulong||v is float||v is double||v is decimal;}
 static bool Same(object a,object b){if(a==null||b==null)return a==b;if(Number(a)&&Number(b))return Convert.ToDouble(a)==Convert.ToDouble(b);var x=a as Dictionary<string,object>;var y=b as Dictionary<string,object>;if(x!=null&&y!=null)return x.Count==y.Count&&x.All(p=>y.ContainsKey(p.Key)&&Same(p.Value,y[p.Key]));if(a is IEnumerable&&!(a is string)&&b is IEnumerable&&!(b is string)){var l=J.List(a).ToArray();var r=J.List(b).ToArray();return l.Length==r.Length&&!l.Where((v,i)=>!Same(v,r[i])).Any();}return a.Equals(b);}
 static void Text(Dictionary<string,object>s){if(J.S(s,"kind")!="text"||!J.ValidId(J.S(s,"id"))||J.S(s,"text").Length>20000||J.List(s["points"]).Any())throw new Exception("No Windows é possível editar textos digitados. A escrita do tablet é preservada.");foreach(var k in new[]{"x","y","boxW","boxH","fontSize"}){var v=Convert.ToDouble(s[k]);if(double.IsNaN(v)||double.IsInfinity(v)||Math.Abs(v)>10000000)throw new Exception("Texto inválido.");}var size=Convert.ToDouble(s["fontSize"]);if(size<8||size>1024)throw new Exception("Tamanho de texto inválido.");}
 public static void Apply(Dictionary<string,object>d,Dictionary<string,object>p){var pages=J.Obj(d["pages"]);var op=J.S(p,"op");if(op=="meta"){if(p.ContainsKey("count")&&(Convert.ToBoolean(d["pdf"])||J.I(p,"count")<J.I(d,"count")))throw new Exception("A organização do PDF e as páginas existentes são preservadas.");foreach(var k in new[]{"name","folder","paper","count","bookmarks","lastPage"})if(p.ContainsKey(k))d[k]=p[k];return;}var index=J.I(p,"page");if(index<0||index>=J.I(d,"count"))throw new Exception("Página inválida.");var key=index.ToString();var old=pages.ContainsKey(key)?J.List(pages[key]).ToList():new List<object>();if(op=="append"){var text=J.Obj(p["stroke"]);Text(text);var existing=old.FirstOrDefault(o=>J.S(J.Obj(o),"id")==J.S(text,"id"));if(existing!=null){if(!Same(existing,text))throw new Exception("O texto foi alterado. Reabra o caderno.");return;}old.Add(text);pages[key]=old;return;}if(op!="page")throw new Exception("Operação desconhecida.");var next=J.List(p["strokes"]).ToList();var frozen=old.Where(o=>J.S(J.Obj(o),"kind","ink")!="text").ToList();var kept=next.Where(o=>J.S(J.Obj(o),"kind","ink")!="text").ToList();if(!Same(frozen,kept))throw new Exception("A escrita e as imagens do tablet não podem ser alteradas no Windows.");var ids=new HashSet<string>();foreach(var item in next){var obj=J.Obj(item);if(!ids.Add(J.S(obj,"id")))throw new Exception("Objeto duplicado.");if(J.S(obj,"kind")=="text"){var previous=old.FirstOrDefault(o=>J.S(J.Obj(o),"id")==J.S(obj,"id"));if(previous==null||!Same(previous,obj))Text(obj);}}pages[key]=next;}
}
}
